	var expected;
	var out;
	var z;

	z = new Complex128( 3.14, -3.14 );
	out = reim( z );
	expected = new Float64Array( [ 3.14, -3.14 ] );
	t.strictEqual( out[ 0 ], expected[ 0 ], 'returns expected value' );
	t.strictEqual( out[ 1 ], expected[ 1 ], 'returns expected value' );

	t.end();
});","lineStart":1,"lineEnd":49,"totalLines":49,"truncated":false}},"title":"repos/pc-lib-3456/complex-float64-reim/test/test.js","time":{"start":1783262138579,"end":1783262138582}},"id":"prt_f32b4d031001246atoyupyBqQB","sessionID":"ses_0cd4b7160ffe1MtK4grj6Hzv6j","messageID":"msg_f32b4c08a001CcHCVaLIoHs0Kg"}}

