'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var Complex128 = require( '@stdlib/complex-float64-ctor' );
var randu = require( '@stdlib/random-base-randu' );
var isArrayLike = require( '@stdlib/assert-is-array-like' );
var pkg = require( './../package.json' ).name;
var reim = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var values;
	var arr;
	var i;

	values = [
		new Complex128( randu(), randu() ),
		new Complex128( randu(), randu() ),
		new Complex128( randu(), randu() )
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		arr = reim( values[ i%values.length ] );
		if ( arr.length === 0 ) {
			b.fail( 'should not be empty' );
		}
	}
	b.toc();
	if ( !isArrayLike( arr ) ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":57,"totalLines":57,"truncated":false}},"title":"repos/pc-lib-3456/complex-float64-reim/benchmark/benchmark.js","time":{"start":1783262142056,"end":1783262142059}},"id":"prt_f32b4dd45001FYrOH0ic3RWiiu","sessionID":"ses_0cd4b7160ffe1MtK4grj6Hzv6j","messageID":"msg_f32b4d5ef001IlptsP1JtKxIXt"}}

